<script setup>
import {ref,computed} from 'vue'
import {siteConfig as c} from '../config/siteConfig'
import ModalShell from './ModalShell.vue'
const category=ref('Todos'),active=ref(null),categories=['Todos',...new Set(c.gallery.map(p=>p.category))],photos=computed(()=>category.value==='Todos'?c.gallery:c.gallery.filter(p=>p.category===category.value));let start=0
const current=computed(()=>photos.value[active.value]);function move(n){active.value=(active.value+n+photos.value.length)%photos.value.length}
</script>
<template><section id="portfolio" class="section portfolio"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">02 / Nosso olhar nos detalhes</p><h2>Seu próximo estilo<br>começa aqui.</h2></div><p>Resultados da Luiza Rais Nails.<br>Toque nas fotos para ver de perto.</p></div><div class="filters" aria-label="Filtrar resultados"><button v-for="cat in categories" :key="cat" :aria-pressed="category===cat" @click="category=cat">{{cat}}</button></div><div class="gallery-grid"><button v-for="(p,i) in photos" :key="p.id" class="gallery-card" @click="active=i"><div><img :src="p.src" :srcset="`${p.small} 480w, ${p.src} 1200w`" sizes="(max-width:600px) 44vw, 23vw" :alt="p.alt" width="600" height="800" loading="lazy"><span class="zoom" aria-hidden="true">↗</span></div><span>{{p.title}}<small>{{p.category}}</small></span></button></div></div></section><ModalShell v-if="active!==null" label="Galeria de resultados" wide @close="active=null"><div class="lightbox" @keydown.left.prevent="move(-1)" @keydown.right.prevent="move(1)" @touchstart="start=$event.changedTouches[0].clientX" @touchend="e=>{const delta=e.changedTouches[0].clientX-start;if(Math.abs(delta)>45)move(delta<0?1:-1)}"><img :src="current.src" :alt="current.alt" width="1000" height="1000"><div class="lightbox-controls"><button aria-label="Foto anterior" @click="move(-1)">←</button><p aria-live="polite">{{current.title}}<small>{{active+1}} / {{photos.length}}</small></p><button aria-label="Próxima foto" @click="move(1)">→</button></div></div></ModalShell></template>
